// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok);
        assertTrue(c.depositsCount() == 1, "exactly one deposit counted");
    }
}
